class Cart:
    def __init__(self, free_shipping_threshold: float = 100.0, shipping_cost: float = 15.0) -> None:
        self.free_shipping_threshold = free_shipping_threshold
        self.shipping_cost = shipping_cost
        self._items = []  # list of (name, unit_price, quantity)
        self._discounts = []  # list of percent values
        self._vouchers = []  # list of fixed amounts

    def add(self, name: str, unit_price: float, quantity: int = 1) -> None:
        self._items.append((name, unit_price, quantity))

    def apply_discount(self, percent: float) -> None:
        """Register a percentage discount on the whole cart. Can be called several times."""
        self._discounts.append(percent)

    def apply_voucher(self, amount: float) -> None:
        """Register a voucher worth a fixed amount. Can be called several times."""
        self._vouchers.append(amount)

    def _items_subtotal(self) -> float:
        return sum(unit_price * quantity for _, unit_price, quantity in self._items)

    def total(self) -> float:
        """Amount to pay: items after discounts plus shipping."""
        subtotal = self._items_subtotal()

        # Determine the single most beneficial discount or voucher.
        best_saving = 0.0

        # Percentage discounts: best single percentage
        for percent in self._discounts:
            saving = subtotal * (percent / 100.0)
            if saving > best_saving:
                best_saving = saving

        # Vouchers: best single voucher, capped at subtotal
        for amount in self._vouchers:
            saving = min(amount, subtotal)
            if saving > best_saving:
                best_saving = saving

        items_after_discount = subtotal - best_saving
        if items_after_discount < 0:
            items_after_discount = 0.0

        # Free shipping threshold checks the value before discounts.
        if subtotal >= self.free_shipping_threshold:
            shipping = 0.0
        else:
            shipping = self.shipping_cost

        return round(items_after_discount + shipping, 2)
